 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const norm=v=>String(v||'').normalize('NFC').replace(/สำนักงานนิคมอุตสาหกรรม|สำนักงานนิคมฯ|นิคมอุตสาหกรรม|นิคมฯ|\s|[()]/g,'').toLowerCase();
 const table=rows=>'<table class="fp-table"><tbody>'+rows.map(r=>'<tr><th scope="row">'+esc(r[0])+'</th><td>'+esc(r[1])+'</td></tr>').join('')+'</tbody></table>';
 const find=name=>plans.find(p=>norm(p.match)===norm(name)||p.key===name||(p.aliases||[]).some(a=>norm(a)===norm(name)));
 const matching=name=>{const p=find(name);return p&&p.key==='bang-pu'?[p,find('bang-pu-north')]:p?[p]:[]};
 window.ieatDiagramPopup=function(name){return matching(name).map(p=>'<section class="fp-estate"><h4>'+esc(p.name)+' · ระบบป้องกันน้ำท่วม</h4>'+table(p.rows)+(p.image?'<button type="button" class="fp-open" data-flood-plan="'+p.key+'">เปิด '+esc(p.name)+' ↗</button>':'')+'<small>ข้อมูลตามเอกสาร: '+esc(p.source)+' · ไม่ใช่ข้อมูลเรียลไทม์</small></section>').join('')};
