 const style=document.createElement('style');style.textContent='.fp-estate h4{color:#003666;margin:14px 0 8px}.fp-table{border-collapse:collapse;width:100%;font:13px Sarabun,sans-serif;color:#173b50;line-height:1.6}.fp-table th,.fp-table td{border:1px solid #d6e3eb;padding:7px 9px;text-align:left;vertical-align:top;overflow-wrap:anywhere}.fp-table th{width:38%;background:#eef5f9;font-weight:600}.fp-estate small{display:block;color:#617684;margin-top:8px}.fp-open{padding:10px 12px;border:1px solid #add2e7;background:#eaf5fb;color:#003666;border-radius:8px;font:600 13px Sarabun,sans-serif;cursor:pointer;margin-top:10px}.fp-dialog{border:0;padding:0;width:min(1160px,96vw);max-width:96vw;height:min(820px,92vh);max-height:92vh;border-radius:14px;box-shadow:0 12px 55px #002b4e55;color:#173b50;font-family:Sarabun,sans-serif}.fp-dialog::backdrop{background:#102c4d80}.fp-shell{height:100%;display:flex;flex-direction:column}.fp-head{display:flex;align-items:center;gap:12px;padding:12px 16px;border-bottom:1px solid #d6e3eb}.fp-head h2{font-size:19px;margin:0;flex:1}.fp-head button{border:0;background:#fbe8eb;color:#a21b32;border-radius:8px;padding:9px 12px;cursor:pointer;font:600 13px Sarabun,sans-serif}.fp-select{padding:8px;font:14px Sarabun,sans-serif;max-width:45vw}.fp-note{font-size:12px;margin:0;padding:7px 16px;background:#fff6df;color:#775b25}.fp-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;min-height:0;flex:1}.fp-canvas{min-height:320px;background:#f0f4f7}.fp-aside{padding:12px;overflow:auto;min-width:0}.fp-aside h3{font-size:16px;margin:0 0 8px}.fp-point-list{display:grid;gap:6px;margin-bottom:12px}.fp-point-list button{padding:8px 10px;border:1px solid #d5e3eb;border-radius:7px;background:white;color:#003666;text-align:left;cursor:pointer;font:13px Sarabun,sans-serif}.fp-point-list button[aria-pressed=true]{background:#e6f4ed;border-color:#4bad31}.fp-pin{border:2px solid white;border-radius:50%;color:white;box-shadow:0 1px 5px #0008;text-align:center;font:bold 12px sans-serif;line-height:24px}.fp-popup{max-width:300px}.fp-popup h3{font-size:16px;margin:0 0 8px}.fp-source{font-size:11px;color:#617684;line-height:1.5}.fp-dialog .leaflet-popup-content{margin:12px!important}@media(max-width:700px){.fp-head{flex-wrap:wrap}.fp-head h2{font-size:16px}.fp-select{max-width:100%;width:100%;order:3}.fp-layout{grid-template-columns:1fr;grid-template-rows:minmax(300px,1fr) 220px}.fp-aside{border-top:1px solid #d6e3eb}.fp-dialog{height:94vh}}';document.head.appendChild(style);
 function open(key){
  if(!window.L)return;
  current=find(key)||plans[0];lastFocus=document.activeElement;
  if(!dialog){dialog=document.createElement('dialog');dialog.className='fp-dialog';dialog.setAttribute('aria-label','ผังระบบป้องกันน้ำท่วมของนิคมอุตสาหกรรม');dialog.innerHTML='<div class="fp-shell"><header class="fp-head"><h2>ผังระบบป้องกันน้ำท่วม</h2><select class="fp-select" aria-label="เลือกผังนิคมอุตสาหกรรม">'+plans.filter(p=>p.image).map(p=>'<option value="'+p.key+'">'+esc(p.name)+'</option>').join('')+'</select><button type="button" data-fp-close>ปิด ✕</button></header><p class="fp-note">ตำแหน่งอ้างอิงในภาพผัง · ยังไม่ใช่พิกัด GPS · ใช้ + / − เพื่อซูม และคลิกจุดเพื่อดูรายละเอียด</p><div class="fp-layout"><div class="fp-canvas" aria-label="แผนผังนิคมฯ แบบโต้ตอบ"></div><aside class="fp-aside"></aside></div></div>';document.body.appendChild(dialog);dialog.querySelector('[data-fp-close]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{if(map){map.remove();map=null}lastFocus?.focus()});dialog.querySelector('select').onchange=e=>show(e.target.value);}
  if(!dialog.open)dialog.showModal();show(current.key);
 }
 function show(key){
  current=find(key);if(map)map.remove();dialog.querySelector('select').value=current.key;
  const aside=dialog.querySelector('.fp-aside');aside.innerHTML='<h3>'+esc(current.name)+'</h3><div class="fp-point-list"></div>'+table(current.rows)+'<p class="fp-source">'+esc(current.source)+'<br>จำนวนและความจุตามเอกสาร ไม่ใช่สถานะอุปกรณ์แบบเรียลไทม์</p>';
  map=L.map(dialog.querySelector('.fp-canvas'),{crs:L.CRS.Simple,minZoom:-5,maxZoom:3,zoomSnap:.25,attributionControl:false});
  const bounds=[[0,0],[current.height,current.width]];L.imageOverlay(current.image,bounds).addTo(map);map.fitBounds(bounds,{padding:[15,15]});
  current.points.forEach((p,i)=>{const rows=p.rows||[['เครื่องสูบไฟฟ้า',p.count+' เครื่อง'],['กำลังสูบรวมสถานี',p.capacity.toLocaleString('th-TH')+' ลบ.ม./ชม.']];const note=p.label?'หมุดอยู่ที่ป้ายชื่อในผัง ใช้เส้นชี้ในภาพเพื่อดูตำแหน่งอ่าง/บ่อ':'ตำแหน่งอ้างอิงจากสัญลักษณ์ในผัง';const marker=L.marker([current.height-p.y,p.x],{icon:L.divIcon({className:'fp-pin',html:'<span>'+String(i+1)+'</span>',iconSize:[28,28],iconAnchor:[14,14]})}).addTo(map);marker.getElement().style.background=p.color||'#e2142d';marker.bindTooltip(esc(p.name),{direction:'top'}).bindPopup('<div class="fp-popup"><h3>'+esc(p.name)+'</h3>'+table(rows)+'<p class="fp-source">'+esc(note)+'<br>'+esc(current.source)+'</p></div>',{maxWidth:320});const b=document.createElement('button');b.textContent=p.name;b.setAttribute('aria-pressed','false');b.onclick=()=>{aside.querySelectorAll('.fp-point-list button').forEach(x=>x.setAttribute('aria-pressed','false'));b.setAttribute('aria-pressed','true');map.setView(marker.getLatLng(),Math.max(map.getZoom(),0));marker.openPopup();if(window.matchMedia('(max-width:600px)').matches)dialog.querySelector('.fp-layout').scrollTop=0};aside.querySelector('.fp-point-list').appendChild(b);});
  requestAnimationFrame(()=>{map.invalidateSize();map.fitBounds(bounds,{padding:[15,15]})});
 }
 document.addEventListener('click',e=>{const b=e.target.closest('[data-flood-plan]');if(b){e.preventDefault();open(b.dataset.floodPlan)}});
